const update = $json;
let chatId, text = '';

// NORMALIZACIÓN ESTRICTA
if (update.message) {
  chatId = update.message.chat.id;
  text = update.message.text || '';
} else if (update.callback_query) {
  chatId = update.callback_query.message.chat.id;
  // AQUÍ ESTÁ LA CLAVE: Leemos el 'data' del botón
  text = update.callback_query.data || '';
}

chatId = chatId ?? update?.message?.chat?.id ?? update?.callback_query?.message?.chat?.id;

return [{ json: { chatId, text, raw: update } }];

const data = $getWorkflowStaticData('global');

const TTL_DAYS = 90;
const now = Date.now();
const loadedAt = Number(data.catalog_cached_at || data.catalogLoadedAt || 0);
const expired = !loadedAt || (now - loadedAt) > TTL_DAYS * 24 * 60 * 60 * 1000;

const catalog = data.catalog;
let memoryEmpty = true;

if (!expired && catalog && Object.keys(catalog).length > 0) {
  let hasOptions = false;

  for (const model of Object.values(catalog)) {
    if (!model || !Array.isArray(model.steps)) continue;
    for (const step of model.steps) {
      if (!step || !Array.isArray(step.options)) continue;
      if (step.options.length > 0) { hasOptions = true; break; }
    }
    if (hasOptions) break;
  }

  memoryEmpty = !hasOptions;
} else {
  memoryEmpty = true; // fuerza recarga si expiró
}

const text = $json.text ?? $json.raw?.message?.text ?? $json.raw?.callback_query?.data ?? '';
const normalizedText = typeof text === 'string' ? text.trim().toLowerCase() : '';
const isReload = normalizedText === '/reload';
const forceReload = isReload;
const shouldReload = forceReload || expired || memoryEmpty;

const items = $input.all();
return items.map(item => ({ json: { ...item.json, memoryEmpty, catalogExpired: expired, forceReload, shouldReload } }));

// --- CARGA DATA-DRIVEN DESDE GOOGLE SHEETS (DB_Maquinas + DB_Opciones)
// Fuentes: nodos "Leer DB_Maquinas" y "Leer DB_Opciones"
const toNum = (v) => {
  if (v === null || v === undefined) return 0;
  const s = String(v).replace(/[^0-9.\-]/g, '');
  const n = parseFloat(s);
  return Number.isFinite(n) ? n : 0;
};
const toInt = (v, d=0) => {
  const n = parseInt(String(v), 10);
  return Number.isFinite(n) ? n : d;
};

// getter flexible (tolerante a sinónimos/ mayúsculas / espacios)
const normKey = (k) => String(k || '').toLowerCase().trim().replace(/\s+/g,'').replace(/[_\-]/g,'');
const getVal = (obj, terms) => {
  if (!obj) return undefined;
  const keys = Object.keys(obj);
  const map = new Map(keys.map(k => [normKey(k), k]));
  for (const t of terms) {
    const nk = normKey(t);
    if (map.has(nk)) return obj[map.get(nk)];
  }
  for (const t of terms) {
    const nk = normKey(t);
    const partial = keys.find(k => normKey(k).includes(nk));
    if (partial) return obj[partial];
  }
  return undefined;
};

const norm = (v) => String(v ?? '').trim().replace(/\s+/g, ' ');
const normLower = (v) => norm(v).toLowerCase();
const isActive = (v) => {
  if (typeof v === 'boolean') return v;
  const s = String(v ?? '').trim().toLowerCase();
  return ['true','1','yes','si','sí','y'].includes(s);
};
const optionSeen = new WeakMap();

// Nota: en n8n, el nombre exacto de los nodos importa:
const maquinasRows = $items("Leer DB_Maquinas").map(i => i.json);
const opcionesRows = $items("Leer DB_Opciones").map(i => i.json);
const preciosRows = $items("Leer DB_Precios").map(i => i.json);

const catalog = {};
const priceMap = new Map();

// 0) Precios (override desde DB_Precios)
for (const row of preciosRows) {
  const modelo = getVal(row, ["modelo","model","maquina","maquina_id"]);
  const paso = getVal(row, ["paso","paso_id","step","step_id"]);
  const opcionValor = getVal(row, ["opcion_valor","value","valor","code","key"]);
  const activo = getVal(row, ["activo","active","habilitado"]);
  if (!isActive(activo)) continue;
  if (!modelo || !paso || !opcionValor) continue;
  const key = `${normLower(modelo)}|${normLower(paso)}|${normLower(opcionValor)}`;
  const precio = toNum(getVal(row, ["precio_extra_usd","precio","price","opcion_precio","extra"]));
  priceMap.set(key, precio);
}

// 1) Máquinas
for (const row of maquinasRows) {
  const modelo = getVal(row, ["modelo","model","id","maquina_id"]);
  if (!modelo) continue;

  const nombre = getVal(row, ["nombre","name","descripcion","description"]) ?? modelo;
  const basePrice = toNum(getVal(row, ["precio_base","base_price","price","precio","costo"]));
  const plantilla = getVal(row, ["plantilla","template","docx","archivo"]);

  catalog[String(modelo)] = {
    id: String(modelo),
    name: String(nombre),
    basePrice,
    plantilla: plantilla ? String(plantilla) : undefined,
    steps: []
  };
}

// 2) Opciones / Pasos
for (const row of opcionesRows) {
  const modelo = getVal(row, ["modelo","model","maquina","maquina_id"]);
  if (!modelo) continue;
  const m = catalog[String(modelo)];
  if (!m) continue;

  const pasoId = getVal(row, ["paso_id","step_id","paso","step"]);
  const pregunta = getVal(row, ["pregunta","paso_pregunta","question","texto"]);
  const orden = toInt(getVal(row, ["paso_orden","order","orden"]), 0);

  if (!pasoId) continue;

  let step = m.steps.find(s => s.id === String(pasoId));
  if (!step) {
    const questionStr = norm(pregunta);
    step = { id: String(pasoId), question: questionStr || 'Selecciona una opción', order: orden, options: [] };
    m.steps.push(step);
  }

  const rawLabel = getVal(row, ["opcion_label","label","etiqueta","nombre_opcion","opcion"]) || getVal(row, ["opcion label","opcion_label","opcionlabel"]);
  const rawValue = getVal(row, ["opcion_valor","value","valor","code","key"]) || rawLabel;

  const labelStr = norm(rawLabel || rawValue);
  let valueStr = norm(rawValue || rawLabel || labelStr);
  if (labelStr === '') continue;

  if (valueStr === '') valueStr = labelStr;

  const priceKey = `${normLower(modelo)}|${normLower(pasoId)}|${normLower(valueStr)}`;
  const price = priceMap.has(priceKey) ? priceMap.get(priceKey) : toNum(getVal(row, ["opcion_precio","price","precio","costo","extra"]));

  const key = `${normLower(labelStr)}|${normLower(valueStr)}`;
  let seenForStep = optionSeen.get(step);
  if (!seenForStep) {
    seenForStep = new Set();
    optionSeen.set(step, seenForStep);
  }
  if (seenForStep.has(key)) continue;
  seenForStep.add(key);

  step.options.push({
    label: labelStr,
    value: valueStr,
    price
  });
}

// 3) Ordenar pasos y (opcional) opciones
for (const mid of Object.keys(catalog)) {
  catalog[mid].steps.sort((a,b) => (a.order ?? 0) - (b.order ?? 0));
}

const base = $items("Verificar Memoria")?.[0]?.json || $items("Normalize Telegram")?.[0]?.json || $json;
const staticData = $getWorkflowStaticData('global');
staticData.catalog = catalog;
staticData.catalogLoadedAt = Date.now();
staticData.catalog_cached_at = staticData.catalogLoadedAt;

return [{ json: { ...base, catalogLoaded: true, models: Object.keys(catalog).length } }];

const { chatId: inputChatId, text, raw } = $json;
const chatId = inputChatId ?? raw?.message?.chat?.id ?? raw?.callback_query?.message?.chat?.id;

const staticData = $getWorkflowStaticData('global');
staticData.cot = staticData.cot || {};
const hasSession = !!staticData.cot?.[chatId];

let action = null;

const setMode = (mode) => {
  if (!mode) return;
  const current = staticData.cot[chatId] || {};
  staticData.cot[chatId] = { ...current, mode: mode.toUpperCase() };
};

const incomingText = raw?.message?.text || '';
const isCommand = incomingText.startsWith('/');
const isReload = incomingText.trim().toLowerCase() === '/reload';

// 1) /reload
if (isReload) {
  action = 'MENU_SELECTION';
}

// 2) /start o comandos
else if (isCommand) {
  action = 'START';

  // Limpia sesión
  staticData.cot[chatId] = {};

}

// 3) Botones (callback_data)
else if (raw?.callback_query?.data) {
  const data = raw.callback_query.data;

  if (data === 'MENU|AVANZADA' || data === 'MODE|ADV') {
    setMode('ADV');
    action = 'MENU_SELECTION';
  } else if (data === 'MODE|FAST') {
    setMode('FAST');
    action = 'MENU_SELECTION';
  } else {
    action = 'COTIZACION_FLOW';
  }
}

// 4) Texto libre cuando ya existe sesión
else if (raw?.message?.text && !raw.message.text.startsWith('/') && hasSession) {
  action = 'COTIZACION_FLOW';
}

// 5) Texto libre sin sesión -> mostrar menú
else if (raw?.message?.text && !raw.message.text.startsWith('/') && !hasSession) {
  action = 'START';
}

if (!action) {
  action = 'START';
}

return [{ json: { chatId, text, action, raw } }];

// --- GENERADOR DE MENÚ DINÁMICO ---
const effectiveChatId = $json.chatId ?? $json.raw?.message?.chat?.id ?? $json.raw?.callback_query?.message?.chat?.id;
const staticData = $getWorkflowStaticData('global');
const catalog = staticData.catalog || {};
const models = Object.keys(catalog); // Obtiene lista: ["CM1100", "MDM4121", etc.]

// Si el catálogo está vacío, advertimos
if (models.length === 0) {
  return [{ json: { 
    chatId: effectiveChatId, 
    raw: $json.raw,
    text: "⚠️ La memoria está vacía. Por favor ejecuta /reload para recargar.", 
    reply_markup: {} 
  }}];
}

// Construimos los botones (2 por fila)
const keyboard = [];
let row = [];

models.forEach((model, index) => {
  row.push({
    text: model, 
    callback_data: `${model}|START` // CLAVE: Esto inicia el flujo de esa máquina
  });

  if (row.length === 2 || index === models.length - 1) {
    keyboard.push(row);
    row = [];
  }
});

// Salida lista para tu nodo HTTP Request o Telegram
const reloadLine = ($json.forceReload === true || $json.catalogLoaded === true)
  ? `✅ Catálogo actualizado: ${models.length} modelos, ${new Date().toLocaleString()}`
  : "";

return [{
  json: {
    chatId: effectiveChatId,
    raw: $json.raw,
    text: `${reloadLine ? reloadLine + "\n\n" : ""}🏭 *Catálogo VC999 Disponible*\n\nSelecciona la máquina que deseas cotizar:`,
    reply_markup: {
      inline_keyboard: keyboard
    }
  }
}];

const DEBUG = false;
const PAGE_SIZE = 12;
const staticData = $getWorkflowStaticData('global');
const catalog = staticData.catalog || {};
staticData.cot = staticData.cot || {};

const { chatId: inputChatId, text, raw } = $json;
const chatId = inputChatId ?? raw?.message?.chat?.id ?? raw?.callback_query?.message?.chat?.id;

// Helpers
const money = (n) => {
  const x = Number(n || 0);
  return x.toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 0 });
};
const toNum = (v) => {
  const s = String(v ?? '').replace(/[^0-9.\-]/g, '');
  const n = parseFloat(s);
  return Number.isFinite(n) ? n : 0;
};
const normText = (v) => String(v ?? '').trim().replace(/\s+/g, ' ');
const optionKey = (label, value) => `${normText(label).toLowerCase()}|${normText(value ?? label).toLowerCase()}`;
const isGenericQuestion = (q) => {
  const normalized = normText(q).toLowerCase();
  if (!normalized) return true;

  const generics = [
    'selecciona una opción',
    'select an option',
    'choose an option'
  ];

  return normalized.length < 4 || generics.some((phrase) => normalized.includes(phrase));
};
const humanizeStepId = (stepId) => {
  const safe = String(stepId ?? '').trim();
  const withSpaces = safe
    .replace(/[_-]+/g, ' ')
    .replace(/([a-z])([A-Z])/g, '$1 $2')
    .trim();

  if (!withSpaces) return 'Paso';

  return withSpaces
    .split(' ')
    .filter(Boolean)
    .map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
    .join(' ');
};
const resolveMode = (state) => (state?.mode || 'ADV').toUpperCase();
const formatSelections = (selections) => {
  if (!Array.isArray(selections) || selections.length === 0) return ['- Sin opciones'];

  return selections.map((sel) => {
    const stepLabel = humanizeStepId(sel.step ?? 'Paso');
    const priceText = toNum(sel.price) > 0 ? ` (+$${money(sel.price)} USD)` : ' (+$0 USD)';
    const valueText = sel.value ?? 'N/A';
    return `- ${stepLabel}: ${valueText}${priceText}`;
  });
};
const newRunId = () => new Date().toISOString();
const buildSelectionsDetailed = (state, machineConfig) => {
  return (state.selections || []).map((sel) => {
    const stepId = sel.stepId || sel.step || sel.id || '';
    const stepConfig = (machineConfig.steps || []).find(
      (s) => String(s.id || '').toLowerCase() === String(stepId).toLowerCase()
    ) || {};
    const optionMatch = (stepConfig.options || []).find((opt) => {
      const optVal = String(opt.value ?? opt.label ?? '').toLowerCase();
      const targetVal = String(sel.value ?? '').toLowerCase();
      return optVal === targetVal;
    }) || {};
    const friendlyStep = humanizeStepId(stepId || stepConfig.id || 'Paso');
    return {
      step: stepId || stepConfig.id || 'STEP',
      label: optionMatch.label ?? optionMatch.value ?? sel.label ?? sel.value ?? friendlyStep,
      value: sel.value ?? optionMatch.value ?? optionMatch.label ?? '',
      price: toNum(sel.price ?? optionMatch.price ?? 0),
    };
  });
};
const resetState = (mode, model, basePrice) => ({
  mode,
  stage: mode === 'FAST' ? 'await_customer_name' : 'config',
  machine: model,
  stepIndex: 0,
  selections: [],
  totalPrice: toNum(basePrice),
  basePrice: toNum(basePrice),
  customer: {},
  payloadFinal: undefined,
  runId: null,
  stepCache: null,
});

let userState = staticData.cot[chatId];

const isCallback = typeof text === 'string' && text.includes('|');
const isStartMachine = isCallback && text.endsWith('|START');
const isPage = isCallback && text.includes('|P|');
const isOpt = isCallback && text.includes('|O|');

let fastIntroResponse = null;
let cleanedAfterQuote = false;

// A) Selección de máquina (inicio)
if (isStartMachine) {
  const model = text.split('|')[0];
  const machine = catalog[model];
  if (!machine) {
    return [{ json: { chatId, raw, text: "⚠️ Error: Máquina no encontrada. Ejecuta /start.", reply_markup: {} } }];
  }

  const mode = resolveMode(userState);

  userState = resetState(mode, model, machine.basePrice);
  staticData.cot[chatId] = { ...userState };

  if (mode === 'FAST') {
    const steps = Array.isArray(machine.steps) ? machine.steps : [];
    const selections = [];
    let totalPrice = toNum(machine.basePrice);
    const warnings = [];

    steps.forEach((step, idx) => {
      const options = Array.isArray(step?.options) ? step.options : [];
      if (options.length === 0) {
        warnings.push(`Paso ${step?.id ?? idx + 1} sin opciones, se omitió.`);
        return;
      }

      const defaultOpt = options.find((opt) => (String(opt.label ?? '')).includes('(Default)')) || options[0];
      const chosenPrice = toNum(defaultOpt.price);

      selections.push({
        step: step?.id ?? `step_${idx + 1}`,
        value: defaultOpt.value ?? defaultOpt.label ?? 'NA',
        price: chosenPrice,
      });

      totalPrice += chosenPrice;
    });

    userState.selections = selections;
    userState.totalPrice = totalPrice;
    userState.stepIndex = steps.length;

    const warningText = warnings.length ? `
⚠️ ${warnings.join(' ')}` : '';
    fastIntroResponse = {
      text: `⚡️ *Modo Rápido activado*
Se seleccionaron las opciones por defecto. Escribe el *nombre del cliente*.${warningText}`,
    };
  }
}

// B) Paginación de opciones
if (isPage) {
  const parts = text.split('|');
  const model = parts[0];
  const stepIndex = Number(parts[2]);
  const pageIndex = Number(parts[3]);

  if (!userState || userState.machine !== model) {
    return [{ json: { chatId, raw, text: "⚠️ Sesión expirada o modelo no coincide. Ejecuta /start.", reply_markup: {} } }];
  }

  if (userState.mode === 'FAST') {
    return [{ json: { chatId, raw, text: "⚡️ Estás en Modo Rápido. Las opciones ya fueron auto-seleccionadas. Envía el nombre del cliente.", reply_markup: {} } }];
  }

  userState.stepCache = userState.stepCache || { stepIndex, stepId: undefined, options: [] };
  userState.stepCache.page = Number.isFinite(pageIndex) && pageIndex >= 0 ? pageIndex : 0;
}

// B) Opción elegida
if (isOpt) {
  const parts = text.split('|');
  const model = parts[0];
  const stepIndex = Number(parts[2]);
  const optIndex = Number(parts[3]);

  if (!userState || userState.machine !== model) {
    return [{ json: { chatId, raw, text: "⚠️ Sesión expirada o modelo no coincide. Ejecuta /start.", reply_markup: {} } }];
  }

  if (userState.mode === 'FAST') {
    return [{ json: { chatId, raw, text: "⚡️ Estás en Modo Rápido. Las opciones ya fueron auto-seleccionadas. Envía el nombre del cliente.", reply_markup: {} } }];
  }

  const machineConfig = catalog[model] || {};
  const steps = Array.isArray(machineConfig.steps) ? machineConfig.steps : [];
  const cached = userState.stepCache || {};
  const cacheOptions = Array.isArray(cached.options) ? cached.options : [];

  let stepId = cached.stepId;
  let chosenValue = null;
  let chosenPrice = 0;

  if (cached.stepIndex === stepIndex && cacheOptions[optIndex]) {
    const opt = cacheOptions[optIndex];
    stepId = stepId ?? cached.stepId ?? steps[stepIndex]?.id ?? `step_${stepIndex + 1}`;
    chosenValue = opt.value ?? opt.label ?? 'NA';
    chosenPrice = toNum(opt.price);
  } else {
    const step = steps[stepIndex] || {};
    const options = Array.isArray(step.options) ? step.options : [];
    const opt = options[optIndex] || {};
    stepId = step.id ?? `step_${stepIndex + 1}`;
    chosenValue = opt.value ?? opt.label ?? 'NA';
    chosenPrice = toNum(opt.price);
  }

  userState.selections.push({ step: stepId, value: chosenValue, price: chosenPrice });
  userState.totalPrice += chosenPrice;
  userState.stepIndex += 1;
  userState.stepCache = null;
}

// C) Texto libre (Nombre / Correo) — solo si ya terminamos pasos
if (!isCallback && userState) {
  const msg = normText(text || '');

  if (userState.stage === "await_customer_name") {
    userState.customer = { ...userState.customer, name: msg };
    userState.stage = "await_customer_email";

    staticData.cot[chatId] = userState;

    return [{ json: { chatId, raw, text: "📝 Ahora escribe el *correo del cliente*:", reply_markup: {}, isFinished: true, userState } }];
  } else if (userState.stage === "await_customer_email") {
    userState.customer = { ...userState.customer, email: msg };
    userState.stage = "done";
  }
}

// Validación de máquina
if (!userState) {
  return [{ json: { chatId, raw, text: "Usa /start y selecciona una máquina para iniciar.", reply_markup: {} } }];
}

const machineConfig = catalog[userState.machine];
if (!machineConfig) {
  return [{ json: { chatId, raw, text: "⚠️ Catálogo no disponible. Ejecuta /start para recargar.", reply_markup: {} } }];
}

const finalizePayload = () => {
  const detailedSelections = buildSelectionsDetailed(userState, machineConfig);
  const runId = userState.runId || newRunId();
  userState.runId = runId;

  const payload = {
    machine: userState.machine,
    basePrice: toNum(machineConfig.basePrice ?? userState.basePrice ?? userState.totalPrice),
    totalPrice: toNum(userState.totalPrice),
    selections: detailedSelections,
    customer: userState.customer,
    runId,
  };

  userState.payloadFinal = payload;
  staticData.cot[chatId] = {
    mode: userState.mode,
    stage: "idle",
    lastRun: runId,
    runId,
    machine: userState.machine,
    customer: {},
    selections: [],
    totalPrice: 0,
    basePrice: toNum(machineConfig.basePrice ?? 0),
  };
  cleanedAfterQuote = true;

  return payload;
};

// D) Render de siguiente paso / cierre
let response = fastIntroResponse || {};
let isFinished = !!fastIntroResponse;

if (!isFinished && userState.stage === "config") {
  const currentIndex = userState.stepIndex;

  if (currentIndex < machineConfig.steps.length) {
    const step = machineConfig.steps[currentIndex];
    const stepOptions = Array.isArray(step.options) ? step.options : [];

    if (stepOptions.length === 0) {
      const debugInfo = DEBUG ? ` [model=${userState.machine}, step=${step.id ?? currentIndex + 1}, steps=${machineConfig.steps.length}, options=${stepOptions.length}]` : '';

      response = {
        text: `⚠️ No hay opciones disponibles para el paso "${step.id ?? currentIndex + 1}". Usa /start para recargar el catálogo o contacta soporte.${debugInfo}`,
        reply_markup: {},
      };
    } else {
      const normalizeStepId = (stepId) => String(stepId ?? '')
        .toUpperCase()
        .trim()
        .replace(/[\s_]+/g, '');

      const STEP_FRIENDLY = {
        "LID": "Lid Height",
        "LIDSIZE": "Lid Height",
        "LIDHEIGHT": "Lid Height",
        "PUMP": "Pump Option",
        "PUMPOPTIONS": "Pump Option",
        "GAS": "Gas Flush",
        "GASFLUSH": "Gas Flush",
        "BIACTIVE": "Bi-Active Sealing",
        "BI ACTIVE": "Bi-Active Sealing",
        "PAS": "Positive Air Sealer",
        "POSITIVEAIRSEALER": "Positive Air Sealer"
      };

      const prettyLabel = (stepId, label, value) => {
        const rawLabel = String(label ?? value ?? '').trim();
        const normalizedId = normalizeStepId(stepId);

        if (rawLabel.length >= 18) return rawLabel;

        const friendly = STEP_FRIENDLY[normalizedId];
        if (!friendly) return rawLabel;

        const normalizeYesNoDisplay = (str) => {
          const normalized = String(str ?? '').trim().toLowerCase();
          if (["si", "sí"].includes(normalized)) return "Sí";
          if (["yes", "true", "y", "1"].includes(normalized)) return "Yes";
          if (["no", "false", "0", "n"].includes(normalized)) return "No";
          return str;
        };

        if (["LID", "LIDSIZE", "LIDHEIGHT"].includes(normalizedId)) {
          const hasInch = /inch/i.test(rawLabel);
          const seemsNumber = /^\s*\d+(\.\d+)?\s*$/.test(rawLabel);
          const enriched = !hasInch && seemsNumber ? `${rawLabel} inch` : rawLabel;
          return `${friendly}: ${enriched}`;
        }

        if (["GAS", "GASFLUSH", "BIACTIVE", "BI ACTIVE", "PAS", "POSITIVEAIRSEALER"].includes(normalizedId)) {
          const display = normalizeYesNoDisplay(rawLabel);
          return `${friendly}: ${display}`;
        }

        if (["PUMP", "PUMPOPTIONS"].includes(normalizedId)) {
          return `${friendly}: ${rawLabel}`;
        }

        return `${friendly}: ${rawLabel}`;
      };

      const questionText = normText(step.question);
      const stepTitle = isGenericQuestion(questionText)
        ? humanizeStepId(step.id ?? `Paso ${currentIndex + 1}`)
        : questionText;

      const existingCache = userState.stepCache && userState.stepCache.stepIndex === currentIndex
        ? userState.stepCache
        : null;

      const stepCache = existingCache || {
        stepIndex: currentIndex,
        stepId: step.id ?? `step_${currentIndex + 1}`,
        options: [],
        page: 0,
      };

      if (!existingCache || stepCache.options.length === 0) {
        const seenOptions = new Set();
        stepOptions.forEach(opt => {
          const price = toNum(opt.price);
          const value = opt.value ?? opt.label ?? 'NA';
          const key = optionKey(opt.label ?? value, value);
          if (seenOptions.has(key)) return;
          seenOptions.add(key);

          const baseLabel = opt.label ?? value;
          stepCache.options.push({ label: baseLabel, value, price });
        });
      }

      const totalOptions = stepCache.options.length;
      const totalPages = Math.max(1, Math.ceil(totalOptions / PAGE_SIZE));
      let page = Number.isFinite(stepCache.page) ? stepCache.page : 0;
      if (page < 0 || page >= totalPages) page = 0;
      stepCache.page = page;

      const start = page * PAGE_SIZE;
      const pageOptions = stepCache.options.slice(start, start + PAGE_SIZE);

      const inline_keyboard = [];
      let row = [];

      pageOptions.forEach((opt, idx) => {
        const priceText = opt.price > 0 ? ` (+$${money(opt.price)})` : '';
        const display = prettyLabel(step.id, opt.label ?? opt.value, opt.value);
        const optIndex = start + idx;

        row.push({
          text: `${display}${priceText}`,
          callback_data: `${userState.machine}|O|${currentIndex}|${optIndex}`
        });

        if (row.length === 2) {
          inline_keyboard.push(row);
          row = [];
        }
      });

      if (row.length) {
        inline_keyboard.push(row);
      }

      if (totalPages > 1) {
        const navRow = [];
        if (page > 0) {
          navRow.push({
            text: '⏮️ Anterior',
            callback_data: `${userState.machine}|P|${currentIndex}|${page - 1}`
          });
        }
        if (page < totalPages - 1) {
          navRow.push({
            text: '⏭️ Siguiente',
            callback_data: `${userState.machine}|P|${currentIndex}|${page + 1}`
          });
        }
        if (navRow.length) {
          inline_keyboard.push(navRow);
        }
      }

      userState.stepCache = stepCache;

      const pageLine = totalPages > 1 ? `
Página ${page + 1}/${totalPages}` : '';

      response = {
        text:
`🛠️ *${userState.machine}* (Paso ${currentIndex + 1}/${machineConfig.steps.length})
💰 Total: $${money(userState.totalPrice)} USD${pageLine}

Selecciona: *${stepTitle}*`,
        reply_markup: { inline_keyboard }
      };
    }

  } else {
    // terminamos configuraciones -> pedir nombre
    userState.stage = "await_customer_name";
    isFinished = true;

    response = {
      text:
`✅ *Cotización lista*
Modelo: *${userState.machine}*
Total: *$${money(userState.totalPrice)} USD*

Escribe el *NOMBRE del Cliente*:`
    };
  }

} else if (userState.stage === "await_customer_name") {
  isFinished = true;
  response = { text: "📝 Ahora escribe el *NOMBRE del cliente*:" };

} else if (userState.stage === "await_customer_email") {
  isFinished = true;
  response = { text: "📝 Ahora escribe el *correo del cliente*:" };

} else if (userState.stage === "done") {
  const payload = userState.payloadFinal || finalizePayload();
  const optionLines = formatSelections(payload.selections).join('\n');
  const summaryText =
`🛠️ *Cotización ${userState.machine}*
*Máquina:* ${userState.machine}
*Base:* $${money(payload.basePrice)} USD
*Opciones:*
${optionLines}
*Total:* $${money(payload.totalPrice)} USD
*Cliente:* ${payload.customer?.name || 'N/A'}
*Correo:* ${payload.customer?.email || 'N/A'}
runId: ${payload.runId}
✅ Confirmo datos. Procediendo a generar y enviar PDF.`;

  response = { text: summaryText, quotePayload: payload, runId: payload.runId };
  isFinished = true;
}

// Persistir estado
const stateToPersist = cleanedAfterQuote ? (staticData.cot[chatId] || userState) : userState;
staticData.cot[chatId] = stateToPersist;

const debugInfo = DEBUG ? { debugBasePrice: { model: userState?.machine, basePrice: machineConfig?.basePrice } } : {};

return [{ json: { chatId, raw, ...response, isFinished, userState, ...debugInfo } }];

const staticData = $getWorkflowStaticData('global') || {};
const catalog = staticData.catalog || {};

const toNum = (v) => {
  const n = parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : 0;
};
const norm = (v) => String(v ?? '').trim();

const userState = $json.userState || {};
const quotePayload = $json.quotePayload || userState.payloadFinal || {};
const customer = quotePayload.customer || userState.customer || {};
const machineId = quotePayload.machine || quotePayload.modelo || userState.machine || '';
const selectionsSource = Array.isArray(quotePayload.selections) ? quotePayload.selections : (Array.isArray(userState.selections) ? userState.selections : []);

let runId = quotePayload.runId || userState.runId || $json.runId;
if (!runId) runId = new Date().toISOString();

const selecciones = selectionsSource.map((sel) => ({
  paso: sel.step ?? sel.stepId ?? sel.label ?? '',
  opcion: sel.value ?? sel.option ?? '',
  precio: Number(sel.price ?? 0),
}));

const baseFromCatalog = catalog[machineId]?.basePrice;
const baseCatalogNum = Number.isFinite(Number(baseFromCatalog)) ? toNum(baseFromCatalog) : NaN;
const totalFinal = toNum(quotePayload.totalPrice ?? userState.totalPrice ?? quotePayload.precio_cambiado ?? 0);
const precioBase = Number.isFinite(baseCatalogNum) ? baseCatalogNum : toNum(quotePayload.basePrice ?? userState.basePrice ?? 0);

const fastapiBody = {
  modelo: machineId,
  nombre_cliente: norm(customer.name ?? quotePayload.customerName ?? userState.customer?.name ?? ''),
  email: norm(customer.email ?? quotePayload.customerEmail ?? userState.customer?.email ?? ''),
  precio_base: precioBase,
  precio_cambiado: totalFinal,
  selecciones,
  runId,
};

const nextState = {
  ...userState,
  runId,
  customer: {
    ...userState.customer,
    ...customer,
    name: fastapiBody.nombre_cliente,
    email: fastapiBody.email,
  },
};

return [{ json: { ...$json, fastapiBody, userState: nextState, quotePayload: quotePayload || undefined, runId } }];

