const res = $json || {};

// Si ya viene binario (HTTP descargó el PDF), preservamos y pasamos el item tal cual.
if ($binary && $binary.data) {
  return [{ json: res, binary: $binary }];
}

// Compatibilidad: si viene en base64, lo convertimos.
const pdf64 = res.pdf_base64 || res.pdfBase64 || '';
if (pdf64) {
  const buffer = Buffer.from(pdf64, 'base64');
  const fileName = res.filename || res.fileName || 'cotizacion.pdf';
  return [{ json: res, binary: { data: { data: buffer, mimeType: 'application/pdf', fileName } } }];
}

// Sin PDF: devolvemos error para que el flujo caiga a la rama falsa.
return [{ json: { ...res, ok: false, error: 'pdf_missing' } }];
